"""Dependency updates qualify actual generated bytes without rewriting provenance."""

import hashlib
import importlib.util
import json
from pathlib import Path

import pytest


ROOT = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location("qualified_demo", ROOT / "tools/refresh_demo_project.py")
refresh = importlib.util.module_from_spec(spec)
spec.loader.exec_module(refresh)


@pytest.fixture
def project(tmp_path, monkeypatch):
    frontend = tmp_path / "gui/frontend"
    frontend.mkdir(parents=True)
    (frontend / "package.json").write_text('{"dependencies":{"generator":"1.0.0"}}\n')
    lock = frontend / "package-lock.json"
    lock.write_text('{"generator":"1.0.0"}\n')
    source = tmp_path / "authoring.py"
    source.write_text("reviewed authoring source\n")
    demo = {"modules": {"example": {"input": 12}}, "engineRevisions": {"example": 1}}
    bundled = tmp_path / "bundled.json"
    exported = tmp_path / "exported.json"
    manifest = tmp_path / "manifest.json"
    for path in (bundled, exported):
        path.write_text(refresh.render(demo))
    monkeypatch.setattr(refresh, "ROOT", tmp_path)
    monkeypatch.setattr(refresh, "DEMO_PATH", bundled)
    monkeypatch.setattr(refresh, "EXAMPLE_DEMO_PATH", exported)
    monkeypatch.setattr(refresh, "MANIFEST_PATH", manifest)
    monkeypatch.setattr(refresh, "authoring_fingerprints", lambda: {
        "authoring.py": hashlib.sha256(source.read_bytes()).hexdigest(),
    })
    monkeypatch.setattr(refresh, "expected_demo", lambda: demo)
    manifest.write_text(refresh.render(refresh.demo_manifest()))
    return {"root": tmp_path, "lock": lock, "source": source, "demo": demo,
            "bundled": bundled, "exported": exported, "manifest": manifest}


def snapshot(project):
    return {name: project[name].read_bytes() for name in ("lock", "source", "bundled", "exported", "manifest")}


def test_dependency_only_change_is_qualified_by_output_equivalence_without_restamping(project):
    recorded = json.loads(project["manifest"].read_text())
    project["lock"].write_text('{"generator":"1.0.1"}\n')
    before = snapshot(project)

    original, candidate = refresh.check_reviewed_artifacts()
    assert original == recorded
    assert original["authoringEnvironment"] != candidate["authoringEnvironment"]
    evidence = refresh.check_generated_artifacts()
    assert evidence["status"] == "passed"
    assert evidence["dependencyEnvironmentChanged"] is True
    assert evidence["candidateDependencies"]["gui/frontend/package-lock.json"] == hashlib.sha256(project["lock"].read_bytes()).hexdigest()
    assert evidence["recordedAuthoringDependencies"] == recorded["authoringEnvironment"]["dependencyFiles"]
    assert evidence["generatedSha256"] == hashlib.sha256(project["bundled"].read_bytes()).hexdigest()
    assert snapshot(project) == before


def test_dependency_change_that_changes_output_fails_without_modifying_artifacts(project, monkeypatch):
    project["lock"].write_text('{"generator":"2.0.0"}\n')
    monkeypatch.setattr(refresh, "expected_demo", lambda: {"modules": {"example": {"input": 99}}})
    before = snapshot(project)
    with pytest.raises(ValueError, match="Candidate dependencies or authoring behavior change"):
        refresh.check_generated_artifacts()
    assert snapshot(project) == before


@pytest.mark.parametrize("target", ["source", "bundled", "exported"])
def test_source_or_artifact_drift_still_fails_static_check(project, target):
    project[target].write_text(project[target].read_text() + " ")
    with pytest.raises(ValueError, match="Demo .* changed"):
        refresh.check_reviewed_artifacts()


def test_missing_recorded_environment_cannot_silently_qualify(project):
    manifest = json.loads(project["manifest"].read_text())
    manifest.pop("authoringEnvironment")
    project["manifest"].write_text(json.dumps(manifest))
    with pytest.raises(ValueError, match="provenance is missing or malformed"):
        refresh.check_generated_artifacts()


def test_dependency_change_during_generation_invalidates_evidence(project, monkeypatch):
    def changing_generator():
        project["lock"].write_text('{"generator":"changed-during-check"}\n')
        return project["demo"]
    monkeypatch.setattr(refresh, "expected_demo", changing_generator)
    with pytest.raises(ValueError, match="changed during generation qualification"):
        refresh.check_generated_artifacts()


def test_static_check_needs_no_node_and_does_not_claim_dependency_qualification(project, monkeypatch, capsys):
    def forbidden_generator():
        raise AssertionError("Python-only static check must not invoke Node")
    monkeypatch.setattr(refresh, "expected_demo", forbidden_generator)
    monkeypatch.setattr(refresh.sys, "argv", ["refresh_demo_project.py", "--check"])
    assert refresh.main() == 0
    assert "does not qualify candidate dependencies" in capsys.readouterr().out


def test_failed_generation_emits_failed_evidence_for_ci(project, monkeypatch):
    output = project["root"] / "evidence/demo.json"
    monkeypatch.setattr(refresh, "expected_demo", lambda: {"modules": {"example": {"input": 99}}})
    monkeypatch.setattr(refresh.sys, "argv", ["refresh_demo_project.py", "--check-generated", "--evidence", str(output)])
    assert refresh.main() == 1
    evidence = json.loads(output.read_text())
    assert evidence["schema"] == "perdura.demo-generation-qualification/v1"
    assert evidence["status"] == "failed"
    assert "reviewed artifacts were not modified" in evidence["error"]
